DO $$ DECLARE body text; BEGIN SELECT prosrc INTO body FROM pg_proc WHERE oid='public.prepare_checkout_for_user(uuid,text,uuid,numeric,numeric)'::regprocedure; body:=replace(body,'current_plan record','current_plan public.plans%ROWTYPE'); EXECUTE format('CREATE OR REPLACE FUNCTION public.prepare_checkout_for_user(_user uuid,_kind text,_target uuid,_usd numeric,_rate numeric) RETURNS json LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS %L',body); END $$;